param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
function Body($s,$n){Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) $n}
$scope=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/State/Vehicles/AICF_UnstuckMutationScope.c'))
$flow=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Vehicles/AICF_VehicleTransitFlow.c'))
$controller=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Bootstrap/AICF_MatchController.c'))
$find=Body $controller 'FindManagedInfantrySlot';$sample=Body $flow 'TryRelocateVehicleForUnstuck'
$start=$sample.IndexOf('bool currentHint =');$end=$sample.IndexOf('vector angles = targetDirection.VectorToAngles();',$start)
if($start-lt0-or$end-le$start){throw 'Missing actual final mutation boundary'}
$boundary=$sample.Substring($start,$end-$start)
if(!$find.Contains('m_bStopped || s_ActiveController != this')){throw 'Stopped/current controller boundary missing'}
if($sample.IndexOf('AICF_UnstuckMutationScope.Capture(trip, vehicle)')-gt$sample.IndexOf('m_Watchdog.CanSafelyRelocateVehicle(')){throw 'Mutation capture follows first callback'}
if(!$boundary.Contains('if (!mutationScope.IsCurrent()) return false;')-or$boundary.IndexOf('if (!mutationScope.IsCurrent()) return false;')-lt$boundary.IndexOf('IsUnstuckCandidateHazardClear(selectedCandidate')){throw 'Missing post-callback unconditional owner recheck'}
$translated=$scope.Replace('protected ','public ').Replace('class AICF_UnstuckMutationScope','public class AICF_UnstuckMutationScope:N').Replace('static AICF_UnstuckMutationScope Capture','public static AICF_UnstuckMutationScope Capture').Replace('bool IsCurrent()','public bool IsCurrent()').Replace('EntityID','int').Replace('vector','Vec').Replace('System.GetTickCount()','Clock.GetTickCount()').Replace('.FindComponent(RplComponent)','.FindComponent(typeof(RplComponent))').Replace('%1:%2:%3:%4:%5:%6:%7:%8','{0}:{1}:{2}:{3}:{4}:{5}:{6}:{7}')
$translatedFind=$find.Replace('AICF_GroupSlot slot;','AICF_GroupSlot slot=null;')
$translatedBoundary=$boundary.Replace('float repeatedNearestPlayer;','double repeatedNearestPlayer=0;').Replace('allowManagedTransitionRecovery, safetyReason)','allowManagedTransitionRecovery, out safetyReason)').Replace('repeatedNearestPlayer, safetyReason)','out repeatedNearestPlayer, out safetyReason)').Replace('vehicle, safetyReason)','vehicle, out safetyReason)')
$cs=@'
using System;using System.Collections.Generic;
namespace AICFMutationActual {
public class N {public static bool operator !(N n){return ReferenceEquals(n,null);}public static implicit operator bool(N n){return !ReferenceEquals(n,null);}}
public struct Vec {public double X,Y,Z;public Vec(double x,double y,double z){X=x;Y=y;Z=z;}public static bool operator==(Vec a,Vec b){return a.X==b.X&&a.Y==b.Y&&a.Z==b.Z;}public static bool operator!=(Vec a,Vec b){return !(a==b);}public override bool Equals(object o){return o is Vec&&this==(Vec)o;}public override int GetHashCode(){return X.GetHashCode();}}
public static class Clock {public static int Now=1000;public static int GetTickCount(){return Now;}}
public static class Replication {public static bool Server=true;public static bool IsServer(){return Server;}}
public enum AICF_ETransportTripPhase {TRANSIT,TACTICAL_DEPLOYMENT}public enum AICF_EVehicleLeaseState {ACTIVE,RELEASED}
public class RplComponent:N {public int Value=1;public bool Master=true,Proxy;public int Id(){return Value;}public static RplComponent Cast(N n){return n as RplComponent;}}
public class Faction:N {public string Key="USSR";public string GetFactionKey(){return Key;}}
public class IEntity:N {public int Id=1;public RplComponent Rpl=new RplComponent();public Vec Origin=new Vec(0,0,0);public int GetID(){return Id;}public Vec GetOrigin(){return Origin;}public N FindComponent(Type t){return Rpl;}}
public class SCR_AIGroup:IEntity {public Faction Faction=new Faction();public Faction GetFaction(){return Faction;}}
public class Vehicle:IEntity {}
public class AICF_GroupSlot:N {public SCR_AIGroup Group;public int Generation=1,Assignment=1,Intent=1,Kind,SlotId;public N Base;public Vec Goal;public bool Ready=true;public int GetSlotId(){return SlotId;}public bool IsCombatReady(){return Ready;}public SCR_AIGroup GetGroup(){return Group;}public int GetSpawnGeneration(){return Generation;}public int GetStrategicAssignmentRevision(){return Assignment;}public int GetStrategicIntentRevision(){return Intent;}public Vec GetTargetPosition(){return Goal;}public int GetTargetKind(){return Kind;}public N GetTargetBase(){return Base;}}
public class AICF_FactionState:N {public AICF_GroupSlot Slot;public AICF_GroupSlot FindSlotByGroup(SCR_AIGroup g){return Slot!=null&&Slot.Group==g?Slot:null;}}
public class AICF_MatchController:N {public static AICF_MatchController s_ActiveController;public bool m_bStarted=true,m_bStopped,m_bRosterReady=true;public AICF_FactionState m_USState,m_USSRState;public static AICF_MatchController GetActiveController(){return s_ActiveController;}public AICF_GroupSlot FindManagedInfantrySlot(SCR_AIGroup group) __FIND__}
public class AICF_StrategicAssignmentSnapshot:N {public SCR_AIGroup Group;public int Assignment=1,Intent=1,Kind;public N Base;public Vec Goal;public SCR_AIGroup GetGroup(){return Group;}public int GetAssignmentRevision(){return Assignment;}public int GetStrategicIntentRevision(){return Intent;}public Vec GetTargetPosition(){return Goal;}public int GetTargetKind(){return Kind;}public N GetTargetBase(){return Base;}}
public class AICF_VehicleLease:N {public Vehicle Vehicle;public int LeaseGeneration=1,VehicleGeneration=1;public bool Physical=true,Identity=true,EntityIdentity=true;public AICF_EVehicleLeaseState State=AICF_EVehicleLeaseState.ACTIVE;public Vehicle GetVehicle(){return Vehicle;}public int GetLeaseGeneration(){return LeaseGeneration;}public int GetVehicleGeneration(){return VehicleGeneration;}public bool HasPhysicalAsset(){return Physical;}public AICF_EVehicleLeaseState GetState(){return State;}public bool MatchesTripIdentity(string f,int s,int g,int t){return Identity;}public bool MatchesEntityIdentity(Vehicle v,int id,string rpl){return EntityIdentity;}}
public class AICF_TransportTrip:N {public AICF_StrategicAssignmentSnapshot Assignment;public AICF_VehicleLease Lease;public bool Valid=true,Terminal,Expired,PresetCurrent=true;public N Preset;public AICF_GroupSlot PresetSlot;public N GetVehiclePreset(){return Preset;}public bool IsVehiclePresetCurrent(){return PresetCurrent;}public AICF_GroupSlot GetVehiclePresetSlot(){return PresetSlot;}public AICF_ETransportTripPhase Phase=AICF_ETransportTripPhase.TRANSIT;public string Faction="USSR";public int Slot,GroupGeneration=1,TripGeneration=1;public bool IsValid(){return Valid;}public bool IsTerminal(){return Terminal;}public bool IsDeadlineReached(int now){return Expired;}public AICF_ETransportTripPhase GetPhase(){return Phase;}public AICF_StrategicAssignmentSnapshot GetAssignment(){return Assignment;}public AICF_VehicleLease GetLease(){return Lease;}public string GetFactionKey(){return Faction;}public int GetSlotId(){return Slot;}public int GetGroupGeneration(){return GroupGeneration;}public int GetTripGeneration(){return TripGeneration;}}
public static class AICF_VehicleBoardingMutationFence {public static bool IsAuthoritativeReplicatedEntity(IEntity e){return e!=null&&e.Rpl!=null&&e.Rpl.Master&&!e.Rpl.Proxy;}}
__SCOPE__
public class AICF_UnstuckPathHint:N {public bool Current=true;public Action OnRead;public bool IsCurrent(){if(OnRead!=null)OnRead();return Current;}}
// Controlled passive-history collaborator; its actual implementation runs in FailedSitesContracts.
public class AICF_UnstuckFailedSites {public bool Prepared=true,Rejected;public bool PreparedCurrent(AICF_TransportTrip t,Vehicle v){return Prepared;}public bool Rejects(AICF_TransportTrip t,Vehicle v,Vec p,double r){return Rejected;}}
public class Config {public double GetHiddenRecoveryPlayerRadiusMeters(){return 0;}}
public class Watchdog {public Action<int> Callback;public int Calls;public bool Safe=true;public bool CanSafelyRelocateVehicle(SCR_AIGroup g,Vehicle v,double radius,bool allow,out string reason){Calls++;if(Callback!=null)Callback(Calls);reason="SAFE";return Safe;}public bool CanApplyHiddenRecovery(Vec origin,Vec candidate,double radius,out double distance,out string reason){Calls++;if(Callback!=null)Callback(Calls);distance=100;reason="SAFE";return Safe;}}
public static class AICF_OverturnRecovery {public static bool CanMutateNow(AICF_TransportTrip t){return true;}}
public class Boundary {public string mode="",searchDiagnostics="";public bool requireFailedSiteProof;public AICF_UnstuckFailedSites failedSites=new AICF_UnstuckFailedSites();public Config m_Config=new Config();public Watchdog m_Watchdog=new Watchdog();public Action HazardCallback;public bool IsUnstuckCandidateHazardClear(Vec p,SCR_AIGroup g,Vehicle v,out string reason){if(HazardCallback!=null)HazardCallback();reason="CLEAR";return true;}
 public bool Check(AICF_TransportTrip trip,Vehicle vehicle,Vec originalPosition,Vec selectedCandidate,AICF_UnstuckMutationScope mutationScope,AICF_UnstuckPathHint pathHint){bool allowManagedTransitionRecovery=true,requireOverturnScope=false;const double UNSTUCK_MIN_DISPLACEMENT_METERS=4;string safetyReason="",selectionDetails="";__BOUNDARY__ return true;}}
public class Environment {public AICF_TransportTrip Trip;public AICF_GroupSlot Slot;public AICF_MatchController Controller;public Vehicle Car;public AICF_UnstuckMutationScope Scope;public static Environment Fresh(){Clock.Now=1000;Replication.Server=true;var group=new SCR_AIGroup();var car=new Vehicle{Id=2};var slot=new AICF_GroupSlot{Group=group};var controller=new AICF_MatchController{m_USState=new AICF_FactionState(),m_USSRState=new AICF_FactionState{Slot=slot}};AICF_MatchController.s_ActiveController=controller;var trip=new AICF_TransportTrip{Assignment=new AICF_StrategicAssignmentSnapshot{Group=group},Lease=new AICF_VehicleLease{Vehicle=car}};var e=new Environment{Trip=trip,Slot=slot,Controller=controller,Car=car};e.Scope=AICF_UnstuckMutationScope.Capture(trip,car);if(e.Scope==null)throw new Exception("positive capture failed");return e;}}
public static class Execute {public static int Run(){int n=0;Action<bool,string>c=(ok,s)=>{if(!ok)throw new Exception(s);n++;};var e=Environment.Fresh();c(e.Scope.IsCurrent(),"positive captured scope");
 Action<Action<Environment>,string>negative=(change,label)=>{var x=Environment.Fresh();change(x);c(!x.Scope.IsCurrent(),label);};
 negative(x=>x.Controller.m_bStopped=true,"stopped controller");negative(x=>AICF_MatchController.s_ActiveController=new AICF_MatchController(),"superseded controller");negative(x=>x.Controller.m_bRosterReady=false,"roster lost");negative(x=>x.Controller.m_bStarted=false,"not started");negative(x=>Replication.Server=false,"client");
 negative(x=>x.Trip.Valid=false,"invalid trip");negative(x=>x.Trip.Terminal=true,"terminal");negative(x=>x.Trip.Expired=true,"original deadline");negative(x=>x.Trip.Phase=AICF_ETransportTripPhase.TACTICAL_DEPLOYMENT,"phase exited");negative(x=>Clock.Now=4001,"real 3001ms expiry");negative(x=>Clock.Now=999,"clock regression");
 negative(x=>x.Trip.Assignment=new AICF_StrategicAssignmentSnapshot(),"assignment replaced");negative(x=>x.Trip.Lease=new AICF_VehicleLease(),"lease replaced");negative(x=>x.Trip.Lease.Vehicle=new Vehicle(),"car replaced");negative(x=>x.Trip.Assignment.Group=new SCR_AIGroup(),"group replaced");negative(x=>x.Slot.Ready=false,"readiness lost");negative(x=>x.Slot.Generation++,"slot generation");negative(x=>x.Slot.Assignment++,"assignment revision");negative(x=>x.Slot.Intent++,"intent revision");negative(x=>x.Slot.Kind++,"target kind");negative(x=>x.Slot.Base=new N(),"target base");negative(x=>x.Slot.Goal=new Vec(1,0,0),"target position");
 negative(x=>x.Trip.GroupGeneration++,"trip group generation");negative(x=>x.Trip.TripGeneration++,"trip generation");negative(x=>x.Trip.Lease.LeaseGeneration++,"lease generation");negative(x=>x.Trip.Lease.VehicleGeneration++,"vehicle generation");negative(x=>x.Trip.Lease.State=AICF_EVehicleLeaseState.RELEASED,"lease state");negative(x=>x.Trip.Lease.Identity=false,"foreign lease");negative(x=>x.Trip.Lease.Physical=false,"missing asset");negative(x=>x.Trip.Lease.EntityIdentity=false,"foreign vehicle lease identity");negative(x=>x.Slot.SlotId++,"wrong numeric slot");negative(x=>{x.Trip.Preset=new N();x.Trip.PresetCurrent=false;},"stale preset");negative(x=>{x.Trip.Preset=new N();x.Trip.PresetSlot=new AICF_GroupSlot();},"foreign preset slot");
 negative(x=>{x.Trip.Lease=null;x.Scope.m_Lease=null;},"both weak lease cleared");negative(x=>{x.Trip.Assignment=null;x.Scope.m_Assignment=null;},"both weak assignment cleared");negative(x=>x.Scope.m_GroupRpl=null,"captured group component gone");negative(x=>x.Scope.m_VehicleRpl=null,"captured car component gone");negative(x=>x.Car.Id++,"car entity id");negative(x=>x.Trip.Assignment.Group.Id++,"group entity id");negative(x=>x.Car.Origin=new Vec(0.001,0,0),"origin drift");negative(x=>x.Car.Rpl=new RplComponent(),"rpl component swap");negative(x=>x.Car.Rpl.Value++,"car rpl id");negative(x=>x.Trip.Assignment.Group.Rpl.Value++,"group rpl id");negative(x=>x.Car.Rpl.Master=false,"proxy nonmaster");negative(x=>x.Car.Rpl.Proxy=true,"proxy flag");negative(x=>x.Trip.Assignment.Group.Faction.Key="US","foreign faction");
 e=Environment.Fresh();e.Trip.Preset=new N();e.Trip.PresetSlot=e.Slot;c(e.Scope.IsCurrent(),"current preset positive");e=Environment.Fresh();e.Trip.Lease.Identity=false;c(AICF_UnstuckMutationScope.Capture(e.Trip,e.Car)==null,"initial foreign lease rejected");e=Environment.Fresh();e.Slot.SlotId++;c(AICF_UnstuckMutationScope.Capture(e.Trip,e.Car)==null,"initial wrong numeric slot");e=Environment.Fresh();e.Controller.m_bStopped=true;c(AICF_UnstuckMutationScope.Capture(e.Trip,e.Car)==null,"initial stopped controller rejected");e=Environment.Fresh();var b=new Boundary();c(b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null)&&b.m_Watchdog.Calls==2,"unknown hint legacy positive final boundary");
 for(int stage=1;stage<=3;stage++){e=Environment.Fresh();var captured=e;int at=stage;b=new Boundary();b.m_Watchdog.Callback=i=>{if(i==at)captured.Trip.Lease=new AICF_VehicleLease{Vehicle=captured.Car};};if(stage==3)b.HazardCallback=()=>captured.Trip.Lease=new AICF_VehicleLease{Vehicle=captured.Car};c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null),"unknown hint callback lease swap stage"+stage);}
 e=Environment.Fresh();var controllerContext=e;b=new Boundary();b.HazardCallback=()=>controllerContext.Controller.m_bStopped=true;c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null),"unknown hint final hazard callback stop");
 e=Environment.Fresh();var clearedContext=e;b=new Boundary();b.HazardCallback=()=>{clearedContext.Trip.Lease=null;clearedContext.Scope.m_Lease=null;};c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null),"unknown hint final weak lease cleared");e=Environment.Fresh();b=new Boundary();var badHint=new AICF_UnstuckPathHint{Current=false};c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,badHint)&&b.m_Watchdog.Calls==0,"stale captured hint no unknown fallback");
 e=Environment.Fresh();var callbackContext=e;b=new Boundary();int reads=0;var hint=new AICF_UnstuckPathHint{OnRead=()=>{if(++reads==2)callbackContext.Trip.Assignment=new AICF_StrategicAssignmentSnapshot();}};c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,hint),"hint final callback assignment swap");
 e=Environment.Fresh();b=new Boundary{requireFailedSiteProof=true};var staleHistory=b;b.HazardCallback=()=>staleHistory.failedSites.Prepared=false;c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null),"final callback stale prepared history veto");
 e=Environment.Fresh();b=new Boundary();var repeatedHistory=b;b.HazardCallback=()=>repeatedHistory.failedSites.Rejected=true;c(!b.Check(e.Trip,e.Car,e.Car.Origin,new Vec(0,0,8),e.Scope,null),"final callback newly failed candidate veto");return n;}}
}
'@
$cs=$cs.Replace('__FIND__',$translatedFind).Replace('__SCOPE__',$translated).Replace('__BOUNDARY__',$translatedBoundary)
Add-Type -TypeDefinition $cs
$actual=[AICFMutationActual.Execute]::Run()
$mutants=@(
 @('post-callback unconditional owner',$cs.Replace('if (!mutationScope.IsCurrent()) return false;',';')),
 @('stopped controller',$cs.Replace('m_bStopped || s_ActiveController != this','s_ActiveController != this')),
 @('foreign lease trip identity',([regex]::Replace($cs,'if \(!m_Lease.MatchesTripIdentity\([^;]+return false;',';')))
)
$k=0
foreach($mutant in $mutants){
 if($mutant[1]-eq$cs){throw "Mutation did not match $($mutant[0])"}
 $name='AICFMutationNegative'+$k;$types=Add-Type -TypeDefinition $mutant[1].Replace('AICFMutationActual',$name) -PassThru
 $execute=$types|Where-Object{$_.FullName-eq($name+'.Execute')};$rejected=$false
 try{$null=$execute.GetMethod('Run').Invoke($null,@())}catch{$rejected=$true}
 if(!$rejected){throw "Executable unsafe mutant escaped $($mutant[0])"};$k++
}
"PASS Unstuck mutation scope: actual_owner_and_sampler_callback_controls=$actual executable_unsafe_mutants=$k native=NOT_RUN"
